practices.solutionCode:
export async function handler(event) {
  if (!Array.isArray(event?.amounts)) throw new TypeError('amounts must be an array');
  let totalCents = 0;
  for (const amount of event.amounts) {
    if (!Number.isSafeInteger(amount) || amount < 0) throw new TypeError('Invalid amount');
    totalCents += amount;
    if (!Number.isSafeInteger(totalCents)) throw new RangeError('Total is too large');
  }
  return { totalCents };
}
